// Resample daily points to weekly means with gap flags (plain JS)
function resampleWeekly(points) {
  // points: [{day: 'YYYY-MM-DD', v}] sorted; weeks keyed by Monday
  const weeks = new Map();
  for (const p of points) {
    const d = new Date(p.day + "T00:00:00Z");
    const monday = new Date(d);
    monday.setUTCDate(d.getUTCDate() - ((d.getUTCDay() + 6) % 7));
    const k = monday.toISOString().slice(0, 10);
    if (!weeks.has(k)) weeks.set(k, []);
    weeks.get(k).push(p.v);
  }
  return [...weeks].map(([week, vs]) => ({ week, n: vs.length, mean: vs.reduce((s, v) => s + v, 0) / vs.length }));
}
